__NUXT_JSONP__("/it/price", (function(a,b,c,d,e,f,g,h,i,j,k,l){return {data:[{details:{slug:b,pageTitle:"Prezzi | Mentor Language Institute",pageDescription:"Il costo dell'alloggio è escluso nel caso in cui lo studente decida di provvedervi personalmente.",title:"Prezzi",image:"\u002Fimages\u002Fprices\u002Fprice\u002Fget-a-quote.jpg",button:{lists:[{link:["\u003Ca class=\"btn btn-primary\" href=\"\u002Fit\u002Fprice-auto\"\u003ECalcolo del prezzo\u003C\u002Fa\u003E"]}]},steps:{title:"①Tassa scolastica+②Costo dell'alloggio+③Altri costi",subtitle:["Il costo dell'alloggio è escluso nel caso in cui lo studente decida di provvedervi personalmente.\u003Cbr\u003E*Please use \u003Ca href=\"\u002Fit\u002Fprice-auto\u002F\"\u003Ethe price calculator\u003C\u002Fa\u003E to get a quote."],lists:[{title:"①Tassa scolastica",subtitle:["Il costo della tassa scolastica varia in base al programma scelto e alla durata.\u003Cbr \u002F\u003E Più a lungo decidi di studiare ad MLI, minore sarà il costo da sostenere."],image:"\u002Fimages\u002Fprices\u002Fprice\u002FPRICE_CHART_WEB_JAN06.jpg",description:["\u003Cb\u003ED&R\u003C\u002Fb\u003E","\u003Cb\u003ED1: Posso pagare le tasse con carta di credito?\u003C\u002Fb\u003E\u003Cbr \u002F\u003E\u003Cb\u003ER1:\u003C\u002Fb\u003E Sì, puoi pagare con carta di credito. Tuttavia verrà aggiunta una commissione del 4%.","\u003Cb\u003ED2: Quali metodi di pagamento posso usare per pagare MLI?\u003C\u002Fb\u003E \u003Cbr \u002F\u003E\u003Cb\u003ER2:\u003C\u002Fb\u003E Accettiamo i seguenti metodi di pagamento: \u003Cbr\u003E • Bonifico bancario \u003Cbr\u003E • Bonifico internazionale \u003Cbr\u003E • Contanti \u003Cbr\u003E • Assegno personale \u003Cbr\u003E • Carta di credito \u003Cbr\u003E • Carta di debito \u003Cbr\u003E • Zelle","Se desideri evitare il costo di servizio del 4% per i pagamenti con carta di credito\u002Fdebito, puoi scegliere una delle seguenti alternative: \u003Cbr\u003E\u003Cb\u003EBonifico bancario, bonifico internazionale (si applica una commissione bancaria di 35 $), contanti, assegno personale o Zelle.\u003C\u002Fb\u003E","\u003Cb\u003ED3: Posso pagare la retta dopo l’inizio del programma? \u003C\u002Fb\u003E\u003Cbr \u002F\u003E\u003Cb\u003ER3:\u003C\u002Fb\u003E No. Il pagamento totale deve essere effettuato prima o il primo giorno del programma."]},{title:"②Costo dell'alloggio",subtitle:["MLI fornisce due opzioni agli studenti: Programma Homestay e Dormitorio. Il Programma Homestay è consigliato per le persone che desiderano avere un'esperienza diretta nella cultura americana. I Dormitori, invece, sono consigliati per gli studenti che vogliono fare nuove conoscenze e condividere esperienze con persone provenienti da diverse parti del mondo."],category:[{title:"Homestay Prices",table:{tableMaxCol:3,title:"Placement Fee* : $300\u003Cbr \u002F\u003E Se il giovane ha meno di 18 anni, l'affitto sarà superiore di circa il 10% rispetto al prezzo per una persona di età superiore ai 18 anni.",thead:[c,d,"Shared***"],tbody:[[e,a,a],[f,"$436","$384"],[g,"$872","$768"],[h,"$1,308","$1,152"],[i,"$1,744","$1,536"],[j,"$3,160","$2,904"],[k,"$4,740","$4,356"]]}},{title:"Prezzi dei Dormitori",table:{tableMaxCol:4,title:"Placement Fee* : $200\u003Cbr \u002F\u003E Se il giovane ha meno di 18 anni, l'affitto sarà superiore di circa il 10% rispetto al prezzo per una persona di età superiore ai 18 anni.",thead:[c,d,"Shared (2 people)","Quad (4 people)"],tbody:[[e,a,a,a],[f,"$570","$430","$315"],[g,"$1,140","$860","$630"],[h,"$1,710","$1,290","$945"],[i,"$2,280","$1,720","$1,260"],[j,"$4,320","$3,080","$2,320"],[k,"$6,480","$4,620","$3,480"]]},description:["*Placement fee is a one time payment. It's not refundable.\u003Cbr \u002F\u003E**Security deposit will be refunded after students have moved out.\u003Cbr \u002F\u003E***If you request a homestay shared room, \u003Cspan class=\"rmarker\"\u003Eyou must apply with another person.\u003C\u002Fspan\u003E","※Your accommodation will be provided by U.S. Support Service Inc. or other agents.","\u003Ca href=\"\u002Fit\u002Fstay\u002F\"\u003E\u003Ci class='bi bi-arrow-right'\u003E\u003C\u002Fi\u003E  More information about Accommodations\u003C\u002Fa\u003E"]}]},{title:"③Costi iniziali",subtitle:["In aggiunta ai costi sopra menzionati, ci sono ulteriori spese iniziali."],lists:["Tassa di registrazione* : $150","Tassa di spedizione dell' I-20 ** : $120","Tassa SEVIS: $350 (pagata direttamente al SEVP) **","Libri di testo: $150-240 ： $150-240"],description:["*non rimborsabile\u003Cbr \u002F\u003E** Per le persone con Visto studenti"]}]},examples:{title:"Esempi",subtitle:["Esempi: 4 settimane e 48 settimane"],lists:[{title:"1 mese(4 settimane)",items:[l,"Tassa di iscrizione: $1,220","Alloggio: $1,630（Dormitory : Quad Rent + Placement Fee + Airport Pickup- oneway)","\u003Cspan class='total'\u003ETotale : $3,000\u003C\u002Fspan\u003E"]},{title:"1 Anno (48 settimane)",items:[l,"Tassa di iscrizione : $10,032","Alloggio: $13,810（Dormitory : Quad Rent + Placement Fee + Airport Pickup- oneway)","\u003Cspan class='total'\u003ETotale : $23,992\u003C\u002Fspan\u003E"]}]},other_info:["Per eventuali domande sui prezzi, contattaci."],dir:"\u002Fprice",path:"\u002Fprice\u002Fit",extension:".json",createdAt:"2026-10-22T16:31:30.175Z",updatedAt:"2026-03-24T13:34:16.710Z"},lang:b}],fetch:{},mutations:void 0}}("$300","it","","Private (Individual)","\u003Cb\u003EDeposit\u003C\u002Fb\u003E","1 week","2 weeks","3 weeks","4 weeks","8 weeks","12 weeks","Tassa di registrazione: $150")));